```jsx
function NewTicketForm({ onCreate }) {
  const [values, setValues] = useState({ subject: '', email: '' });
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);

  function update(field, value) {
    setValues((current) => ({ ...current, [field]: value }));
  }

  async function handleSubmit(event) {
    event.preventDefault();
    if (submitting) return;

    const found = validateTicketForm(values); // a pure function, no React inside
    setErrors(found);
    if (Object.keys(found).length > 0) return;

    setSubmitting(true);
    try {
      await onCreate(values);
      setValues({ subject: '', email: '' });
    } finally {
      setSubmitting(false); // runs on failure too, so the form never sticks
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <label htmlFor="subject">Subject</label>
      <input
        id="subject"
        value={values.subject}
        onChange={(event) => update('subject', event.target.value)}
        aria-invalid={Boolean(errors.subject)}
        aria-describedby={errors.subject ? 'subject-error' : undefined}
      />
      {errors.subject && <p id="subject-error">{errors.subject}</p>}

      <button type="submit" disabled={submitting}>
        {submitting ? 'Creating…' : 'Create ticket'}
      </button>
    </form>
  );
}
```

Three details are doing the real work. `update` uses the updater form, so two fast keystrokes cannot overwrite each other. `validateTicketForm` is a plain function that takes values and returns messages, so it can be checked on its own. And `setSubmitting(false)` is in a `finally`, which is the difference between a form that recovers from a failed save and one that has to be reloaded.

solution.code:
function validateTicketForm(values) {
  const errors = {};
  if (values.subject.trim() === '') {
    errors.subject = 'Enter a subject';
  }
  if (!/^[^@\s]+@[^@\s]+$/.test(values.email)) {
    errors.email = 'Enter a valid email address';
  }
  if (values.description.trim().length < 10) {
    errors.description = 'Describe the problem in at least 10 characters';
  }
  return errors;
}

