function mapTicketResponse(payload) {
  const labels = {
    open: 'Open',
    pending_customer: 'Waiting on customer',
    resolved: 'Resolved',
  };
  const commentCount = payload.comment_count ?? 0;
  return {
    id: payload.id,
    subject: payload.subject,
    statusLabel: labels[payload.status] ?? 'Unknown',
    assigneeName: payload.assignee ? payload.assignee.name : 'Unassigned',
    createdAt: payload.created_at,
    commentCount: commentCount,
    hasComments: commentCount > 0,
  };
}

