solution.code:
function selectListView(state) {
  if (state.status === 'error') {
    return { view: 'error', message: state.error };
  }
  if (state.status === 'loading' && state.items.length > 0) {
    return { view: 'ready', items: state.items, refreshing: true };
  }
  if (state.status === 'idle' || state.status === 'loading') {
    return { view: 'loading' };
  }
  if (state.items.length === 0) {
    if (state.query.trim() === '') {
      return { view: 'empty' };
    }
    return { view: 'no-matches', query: state.query };
  }
  return { view: 'ready', items: state.items, refreshing: false };
}

